SELECT 'INPUT' AS direction, g.input_lot_id AS lot_id, g.quantity, l.definition_id, g.created_at FROM emc_lot_genealogy g LEFT JOIN emc_material_lot l ON l.lot_id = g.input_lot_id WHERE g.output_lot_id = ? UNION ALL SELECT 'OUTPUT' AS direction, g.output_lot_id AS lot_id, g.quantity, l.definition_id, g.created_at FROM emc_lot_genealogy g LEFT JOIN emc_material_lot l ON l.lot_id = g.output_lot_id WHERE g.input_lot_id = ? ORDER BY created_at
